const money = n => n == null || Number.isNaN(Number(n)) ? "—" : Math.round(n).toLocaleString("en-GB") + " gp";
const num = n => n == null || Number.isNaN(Number(n)) ? "—" : Math.round(n).toLocaleString("en-GB");
const pct = n => n == null || Number.isNaN(Number(n)) ? "—" : `${n >= 0 ? "+" : ""}${n.toFixed(2)}%`;
const taxFor = sell => Math.min(Math.floor((sell || 0) * TAX_RATE), TAX_CAP);

function safeRead(key, fallback) {
  try { const value = JSON.parse(localStorage.getItem(key) || "null"); return value ?? fallback; } catch { return fallback; }
}
function parseGp(value) {
  if (typeof value === "number") return value;
  const s = String(value ?? "").trim().toLowerCase().replace(/,/g, "");
  if (!s) return NaN;
  const m = s.match(/^(-?\d+(?:\.\d+)?)([kmb])?$/);
  if (!m) return Number(s);
  const multipliers = { k: 1e3, m: 1e6, b: 1e9 };
  return Number(m[1]) * (multipliers[m[2]] || 1);
}
function fuzzyScore(query, text) {
  const q = query.toLowerCase().trim(), t = text.toLowerCase();
  if (!q) return 0;
  if (t === q) return 10000;
  if (t.startsWith(q)) return 8000 - t.length;
  if (t.includes(q)) return 6000 - t.indexOf(q);
  let qi = 0, gaps = 0;
  for (let i = 0; i < t.length && qi < q.length; i++) { if (t[i] === q[qi]) qi++; else gaps++; }
  if (qi === q.length) return 3000 - gaps;
  let dist = 0;
  for (let i = 0; i < Math.min(4, q.length); i++) if (!t.includes(q.slice(i, i + 2))) dist++;
  return dist <= 2 ? 1000 - t.length : -1;
}
function fuzzyItems(items, query, limit = 10) {
  const q = query.trim();
  if (!q) return [];
  return items.map(x => ({ x, score: fuzzyScore(q, x.name) })).filter(a => a.score >= 0).sort((a,b) => b.score - a.score).slice(0, limit).map(a => a.x);
}
function enrich(row, mapping, hourly = {}) {
  const m = mapping[row.id] || {};
  // Wiki API semantics: high = instant buy price; low = instant sell price.
  const buy = row.high ?? 0;
  const sell = row.low ?? 0;
  const tax = taxFor(sell);
  const margin = sell - buy - tax;
  const volume = hourly[row.id] ? (hourly[row.id].highPriceVolume || 0) + (hourly[row.id].lowPriceVolume || 0) : 0;
  return { ...row, ...m, buy, sell, tax, margin, roi: buy ? margin / buy * 100 : 0, volume,
    potentialProfit: margin * (m.limit || 0), buyUpdated: row.highTime ? row.highTime * 1000 : null,
    sellUpdated: row.lowTime ? row.lowTime * 1000 : null, lastUpdated: Math.max(row.highTime || 0, row.lowTime || 0) * 1000 || null };
}
async function api(path) {
  const res = await fetch(`${API}${path}`, { headers: { "User-Agent": "OSRSFlipIt/1.0" } });
  if (!res.ok) throw new Error(`${res.status} ${res.statusText}`);
  return res.json();
}
function iconUrl(icon) { return icon ? `https://oldschool.runescape.wiki/images/${encodeURIComponent(icon.replace(/ /g, "_"))}` : ""; }
function closeOnEscape(handler) { useEffect(() => { const f = e => e.key === "Escape" && handler(); window.addEventListener("keydown", f); return () => window.removeEventListener("keydown", f); }, [handler]); }

